// Источник: web-тест .qa/e2e/tests/impact-map/im-01-invite-dialog-text-and-share.spec.ts, план .qa/e2e/specs/impact-map.md (23.1), кейс .qa/tests/impact-map/IM-01-invite-dialog-text-and-share.md
// Тикет #6a86f7e6. Опора: реджект 03.10 «מה רצוי» (нусах, утверждённый владелицей 24.09.2026; «החלון מציג בדיוק את הנוסח הזה»), ответ e0b15ba.
// «המשך לשיתוף» открывает системное окно «Поделиться» — не автоматизируем: проверяем своё окно (точный текст + одна ссылка) и что «ביטול» закрывает его.
import { $$, driver, expect } from '@wdio/globals';
import { byText, byTextContains, tapText, expectVisibleText, expectTextContains, scrollToText } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const MESSAGE = 'אני מתפלל עם האפליקציה אור הגאולה — זמני תפילה, הנוסח שלי ותזכורות. מצטרף להתחזק איתי?';
const LINK = 'https://zichui-harabim.expo.app/?invite=c750744f-6d79-4dd5-a891-0b3446eb08cd';

describe('«מפת השפעה» и приглашение', () => {
  afterEach(async () => { await toHome(); });

  it('IM-01 «הזמנת אדם להתחזק» — утверждённый текст и одна ссылка в окне; «ביטול» закрывает без отправки #6a86f7e6 @prod-safe', async () => {
    // 1. «המסע שלי» → «מפת השפעה» → «הזמנת אדם להתחזק».
    await goTab('המסע שלי');
    await (await byText('המסע שלי')).waitForDisplayed({ timeout: 20000 });
    const w = await byTextContains('עלית דרגה');
    if (await w.waitForDisplayed({ timeout: 1500 }).then(() => true, () => false)) await tapText('סגירה');
    await scrollToText('מפת השפעה');
    await (await scrollToText('הזמנת אדם להתחזק')).click();

    // 2. Окно: пояснение, точный текст, ссылка ровно одна, без «אפליקציית»; «ביטול» и «המשך לשיתוף».
    await expectTextContains('זו ההודעה שתישלח, בלי שום פרט נוסף:');
    await expectTextContains(MESSAGE);
    await expectTextContains(LINK);
    const src = await driver.getPageSource();
    expect(src.split(LINK).length - 1).toBe(1);
    await expect(byTextContains('אפליקציית')).not.toBeDisplayed();
    await expectVisibleText('המשך לשיתוף');

    // 3. «ביטול» — окно закрыто, системное окно не открывалось.
    await tapText('ביטול');
    await expect(byTextContains(MESSAGE)).not.toBeDisplayed();
    await expectVisibleText('מפת השפעה');
  });
});
